#!/usr/bin/env python3
"""Replicated key-value store with durable leader/follower replication."""

import asyncio
import json
import os
import sys

import recovery

DATA_DIR = "/app/data"


class WAL:
    """Append-only WAL with explicit fsync and tolerant startup recovery."""

    def __init__(self, path):
        self.path = path
        self.entries = []
        os.makedirs(os.path.dirname(path), exist_ok=True)
        self._load()

    def _decode(self, line):
        entry = json.loads(line.decode('utf-8'))
        if not isinstance(entry, dict):
            raise ValueError('WAL entry is not an object')
        op = entry.get('op')
        if op not in ('SET', 'DEL') or not isinstance(entry.get('key'), str):
            raise ValueError('invalid WAL operation')
        if op == 'SET' and 'value' not in entry:
            raise ValueError('SET entry has no value')
        if op == 'DEL' and len(entry) > 2:
            # Extra fields are harmless, but avoid accepting a malformed SET
            # as a DEL merely because its value was truncated away.
            if entry.get('op') == 'DEL':
                pass
        return entry

    def _load(self):
        try:
            with open(self.path, 'rb') as f:
                raw = f.read()
        except FileNotFoundError:
            return

        offset = 0
        for line in raw.splitlines(keepends=True):
            if not line.endswith(b'\n'):
                # A process can be killed midway through append.  Such an
                # entry was never acknowledged and is safely discarded.
                break
            try:
                entry = self._decode(line[:-1])
            except (UnicodeDecodeError, json.JSONDecodeError, ValueError):
                break
            self.entries.append(entry)
            offset += len(line)

        if offset != len(raw):
            with open(self.path, 'r+b') as f:
                f.truncate(offset)
                f.flush()
                os.fsync(f.fileno())

    def sync(self):
        with open(self.path, 'ab') as f:
            os.fsync(f.fileno())

    def append(self, entry):
        payload = json.dumps(entry, separators=(',', ':')).encode('utf-8') + b'\n'
        idx = len(self.entries)
        with open(self.path, 'ab') as f:
            start = os.fstat(f.fileno()).st_size
            try:
                f.write(payload)
                f.flush()
                os.fsync(f.fileno())
            except Exception:
                f.truncate(start)
                f.flush()
                os.fsync(f.fileno())
                raise
        self.entries.append(entry)
        return idx

    @property
    def last_index(self):
        return len(self.entries) - 1


class KVState:
    def __init__(self, wal_path):
        self.wal = WAL(wal_path)
        self.data = {}
        self.applied_up_to = -1

    def _apply(self, entry):
        op = entry.get('op')
        if op == 'SET':
            self.data[entry['key']] = entry['value']
        elif op == 'DEL':
            self.data.pop(entry['key'], None)

    def apply_through(self, index):
        if index < self.applied_up_to:
            return
        if index >= len(self.wal.entries):
            raise IndexError('cannot apply a missing WAL entry')
        while self.applied_up_to < index:
            self.applied_up_to += 1
            self._apply(self.wal.entries[self.applied_up_to])

    def get(self, key):
        return self.data.get(key)

    def propose(self, op, key, value=None):
        entry = {'op': op, 'key': key}
        if value is not None:
            entry['value'] = value
        return self.wal.append(entry)


class ReplicatedKV:
    def __init__(self, role, port, peer_host=None, peer_port=None):
        self.role = role
        self.port = port
        self.peer_host = peer_host
        self.peer_port = peer_port
        self.state = KVState(os.path.join(DATA_DIR, f"node_{port}.wal"))
        self.mark_path = os.path.join(DATA_DIR, f"node_{port}.mark")
        self.sync_path = os.path.join(DATA_DIR, f"node_{port}.sync")
        self.ack_index = -1
        self.write_lock = asyncio.Lock()
        self._peer_last = None
        self._recover()

    @staticmethod
    def _load_mark(path):
        try:
            with open(path, 'rb') as f:
                value = int(f.read().strip())
            return value if value >= -1 else -1
        except (OSError, ValueError):
            return -1

    def _recover(self):
        loaded = max(self._load_mark(self.mark_path),
                     recovery.load_manifest(self.sync_path))
        target = min(loaded, self.state.wal.last_index)
        if target >= 0:
            self.state.apply_through(target)
        self.ack_index = target
        # Align both metadata files so a later promotion/cold start cannot
        # choose an older point than the one just recovered.
        recovery.save_manifest(self.sync_path, self.ack_index)
        recovery.save_manifest(self.mark_path, self.ack_index)

    async def _handle(self, reader, writer):
        try:
            while True:
                line = await reader.readline()
                if not line:
                    break
                cmd = line.decode(errors='replace').strip()
                if not cmd:
                    continue
                resp = await self._dispatch(cmd)
                writer.write((resp + '\n').encode())
                await writer.drain()
        except (ConnectionResetError, BrokenPipeError, asyncio.IncompleteReadError):
            pass
        finally:
            try:
                writer.close()
                await writer.wait_closed()
            except Exception:
                pass

    async def _dispatch(self, line):
        try:
            parts = line.split()
            if not parts:
                return "ERR"
            cmd = parts[0].upper()
            if cmd == 'GET':
                return self._cmd_get(parts)
            if cmd == 'SET':
                return await self._cmd_set(line)
            if cmd == 'DEL':
                return await self._cmd_del(line)
            if cmd == 'FLUSH':
                return await self._cmd_flush()
            if cmd == 'REPLICATE':
                return self._cmd_replicate(line)
            if cmd == 'COMMIT':
                return self._cmd_commit(parts)
            if cmd == 'PROMOTE':
                return await self._cmd_promote()
            if cmd == 'STATUS':
                return self._cmd_status()
            if cmd == 'LAST':
                return f"ACK {self.state.wal.last_index}"
            return f"ERR unknown: {cmd}"
        except (IndexError, ValueError):
            return "ERR"

    def _cmd_get(self, parts):
        if len(parts) != 2:
            return "ERR usage: GET <key>"
        value = self.state.get(parts[1])
        return f"OK {value}" if value is not None else "NIL"

    @staticmethod
    def _entry(op, key, value=None):
        entry = {'op': op, 'key': key}
        if value is not None:
            entry['value'] = value
        return entry

    def _persist_commit(self, idx):
        """Apply and durably checkpoint an index before it is acknowledged."""
        idx = int(idx)
        if idx < -1 or idx >= len(self.state.wal.entries):
            raise ValueError('commit index outside WAL')
        self.state.apply_through(idx)
        self.ack_index = max(self.ack_index, idx)
        # Either file alone is sufficient during recovery.  Updating both
        # atomically and in either order is therefore crash-safe.
        recovery.save_manifest(self.sync_path, self.ack_index)
        recovery.save_manifest(self.mark_path, self.ack_index)

    async def _cmd_set(self, line):
        if self.role != 'leader':
            return "ERR_NOT_LEADER"
        parts = line.split(maxsplit=3)
        if len(parts) != 4:
            return "ERR usage: SET <key> <value>"
        key, value = parts[2], parts[3]
        async with self.write_lock:
            try:
                idx = self.state.propose('SET', key, value)
                self.state.apply_through(idx)
                self._persist_commit(idx)
            except Exception:
                return "ERR_REPLICATE"
            if self.peer_port and not await self._send_replicate(
                    idx, 'SET', key, value):
                return "ERR_REPLICATE"
            return f"OK {idx}"

    async def _cmd_del(self, line):
        if self.role != 'leader':
            return "ERR_NOT_LEADER"
        parts = line.split(maxsplit=2)
        if len(parts) != 3:
            return "ERR usage: DEL <key>"
        key = parts[2]
        async with self.write_lock:
            try:
                idx = self.state.propose('DEL', key)
                self.state.apply_through(idx)
                self._persist_commit(idx)
            except Exception:
                return "ERR_REPLICATE"
            if self.peer_port and not await self._send_replicate(idx, 'DEL', key):
                return "ERR_REPLICATE"
            return f"OK {idx}"

    async def _cmd_flush(self):
        if self.role != 'leader':
            return "ERR_NOT_LEADER"
        async with self.write_lock:
            target = self.ack_index
            self.state.wal.sync()
            self._persist_commit(target)
            # Best-effort catch-up lets a restarted follower receive history
            # before it is promoted; local durability is already complete.
            if self.peer_port:
                await self._sync_peer_through(target)
            return f"OK {self.ack_index}"

    def _cmd_replicate(self, line):
        if self.role != 'follower':
            return "ERR_NOT_LEADER"
        # Four fixed protocol fields plus the remainder as the value preserves
        # spaces in replicated SET commands.
        parts = line.split(' ', 4)
        if len(parts) < 4:
            return "ERR"
        _, idx_text, op, key = parts[:4]
        try:
            idx = int(idx_text)
        except ValueError:
            return "ERR"
        if op not in ('SET', 'DEL'):
            return "ERR"
        value = parts[4] if len(parts) == 5 and op == 'SET' else None
        if op == 'SET' and len(parts) != 5:
            return "ERR"
        entry = self._entry(op, key, value)
        last = self.state.wal.last_index
        try:
            if idx == last + 1:
                self.state.wal.append(entry)
            elif 0 <= idx <= last:
                if self.state.wal.entries[idx] != entry:
                    return "ERR_REPLICATE"
            else:
                return "ERR_REPLICATE"
            self._persist_commit(idx)
        except Exception:
            return "ERR_REPLICATE"
        return f"ACK {idx}"

    def _cmd_commit(self, parts):
        if self.role != 'follower':
            return "ERR_NOT_LEADER"
        try:
            idx = int(parts[1])
            if idx < -1 or idx > self.state.wal.last_index:
                return "ERR"
            self._persist_commit(idx)
        except (ValueError, IndexError, Exception):
            return "ERR"
        return f"ACK {idx}"

    async def _cmd_promote(self):
        async with self.write_lock:
            try:
                recovery.on_promote(self.state)
                self.ack_index = self.state.wal.last_index
                recovery.save_manifest(self.sync_path, self.ack_index)
                recovery.save_manifest(self.mark_path, self.ack_index)
                self.role = 'leader'
                self.peer_host = None
                self.peer_port = None
            except Exception:
                return "ERR"
            return "OK"

    def _cmd_status(self):
        return (f"role={self.role} applied={self.state.applied_up_to} "
                f"wal_last={self.state.wal.last_index}")

    async def _send_command(self, command):
        reader = writer = None
        try:
            reader, writer = await asyncio.open_connection(
                self.peer_host, self.peer_port)
            writer.write((command.rstrip() + '\n').encode())
            await writer.drain()
            response = await asyncio.wait_for(reader.readline(), timeout=5.0)
            return response.decode(errors='replace').strip()
        except Exception:
            return None
        finally:
            if writer is not None:
                writer.close()
                try:
                    await writer.wait_closed()
                except Exception:
                    pass

    async def _peer_last_index(self):
        response = await self._send_command('LAST')
        if response and response.startswith('ACK '):
            try:
                return int(response[4:])
            except ValueError:
                return None
        return None

    async def _send_replicate_one(self, idx, entry):
        command = f"REPLICATE {idx} {entry['op']} {entry['key']}"
        if 'value' in entry:
            command += f" {entry['value']}"
        response = await self._send_command(command)
        if response == f"ACK {idx}":
            self._peer_last = idx
            return True
        self._peer_last = None
        return False

    async def _sync_peer_through(self, target):
        peer_last = await self._peer_last_index()
        if peer_last is None:
            return False
        if peer_last < target and target >= len(self.state.wal.entries):
            return False
        for idx in range(peer_last + 1, target + 1):
            if idx >= len(self.state.wal.entries):
                return False
            if not await self._send_replicate_one(
                    idx, self.state.wal.entries[idx]):
                return False
        return True

    async def _send_replicate(self, idx, op, key, value=None):
        # Discover the follower's durable tail at least once and after every
        # failure so a restarted follower can be brought up to date.
        if self._peer_last is None:
            self._peer_last = await self._peer_last_index()
        if self._peer_last is None:
            return False
        entry = self._entry(op, key, value)
        if self._peer_last < idx - 1:
            if not await self._sync_peer_through(idx - 1):
                return False
        return await self._send_replicate_one(idx, entry)

    async def run(self):
        server = await asyncio.start_server(self._handle, '0.0.0.0', self.port)
        async with server:
            await server.serve_forever()


def main():
    role = sys.argv[1]
    port = int(sys.argv[2])
    peer_host = sys.argv[3] if len(sys.argv) > 3 else None
    peer_port = int(sys.argv[4]) if len(sys.argv) > 4 else None
    node = ReplicatedKV(role, port, peer_host=peer_host, peer_port=peer_port)
    asyncio.run(node.run())


if __name__ == '__main__':
    main()
